-- FINAL readback evidence; written only after the complete source, projection
-- and report checks. It is not evidence that a notice POST has settled.
CREATE TABLE IF NOT EXISTS continuous_final_notice_evidence (
 operation_token TEXT PRIMARY KEY,
 spreadsheet_id TEXT NOT NULL,
 epoch_id TEXT NOT NULL,
 expense_id TEXT NOT NULL,
 source_version INTEGER NOT NULL CHECK(source_version>0),
 operation_kind TEXT NOT NULL CHECK(operation_kind IN ('CONFIRM','CANCEL')),
 source_revision INTEGER NOT NULL CHECK(source_revision>=0),
 source_digest TEXT NOT NULL CHECK(length(source_digest)=64 AND source_digest NOT GLOB '*[^0-9a-f]*'),
 journal_manifest TEXT NOT NULL CHECK(json_valid(journal_manifest) AND json_type(journal_manifest)='array' AND json_array_length(journal_manifest)>0),
 created_at TEXT NOT NULL
);
CREATE TRIGGER IF NOT EXISTS continuous_final_notice_evidence_insert BEFORE INSERT ON continuous_final_notice_evidence
WHEN NOT EXISTS(SELECT 1 FROM stable_workbook_claims c JOIN stable_recovery_epochs e ON e.spreadsheet_id=c.spreadsheet_id AND e.epoch_id=NEW.epoch_id JOIN stable_recovery_operations o ON o.epoch_id=e.epoch_id AND o.operation_token=c.operation_token JOIN sync_jobs j ON j.entity_type='EXPENSE' AND j.entity_key=e.target_key AND j.entity_version=e.target_version JOIN expense_events src ON src.expense_id=j.entity_key AND src.version=j.entity_version JOIN stable_source_revision rev ON rev.singleton=1 WHERE c.spreadsheet_id=NEW.spreadsheet_id AND c.operation_token=NEW.operation_token AND c.state='HELD' AND c.notice_stamp IS NOT NULL AND c.notice_identity IS NOT NULL AND e.state='ARMED' AND e.target_type='EXPENSE' AND e.target_key=NEW.expense_id AND e.target_version=NEW.source_version AND o.state='ADMITTED' AND j.status='PROCESSING' AND j.lease_token IS NOT NULL AND j.lease_until>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND rev.revision=NEW.source_revision AND ((NEW.operation_kind='CONFIRM' AND src.status='CONFIRMED') OR (NEW.operation_kind='CANCEL' AND src.status='CANCELLED')))
 OR EXISTS(SELECT 1 FROM failed_jobs f WHERE f.queue_name='malipang-jobs' AND f.job_key='EXPENSE:'||NEW.expense_id||':'||NEW.source_version AND f.status='OPEN' AND f.error='DEAD_LETTER_MAX_RETRIES')
 OR (SELECT count(*) FROM json_each(NEW.journal_manifest) item WHERE json_extract(item.value,'$.entity_id')=NEW.expense_id AND json_extract(item.value,'$.projection')='DAILY')<>1
 OR (NEW.operation_kind='CONFIRM' AND (SELECT count(*) FROM json_each(NEW.journal_manifest) item WHERE json_extract(item.value,'$.entity_id')=NEW.expense_id AND json_extract(item.value,'$.projection')='EXPENSE_RAW')<>1)
 OR (SELECT count(*) FROM json_each(NEW.journal_manifest))<>(SELECT count(*) FROM (SELECT json_extract(item.value,'$.entity_id'),json_extract(item.value,'$.projection') FROM json_each(NEW.journal_manifest) item GROUP BY 1,2))
 OR (SELECT count(*) FROM stable_projection_writes p WHERE p.spreadsheet_id=NEW.spreadsheet_id AND p.entity_type='EXPENSE' AND (p.entity_id=NEW.expense_id OR substr(p.entity_id,1,length(NEW.expense_id)+1)=NEW.expense_id||'|'))<>json_array_length(NEW.journal_manifest)
 OR EXISTS(SELECT 1 FROM json_each(NEW.journal_manifest) item WHERE NOT EXISTS(SELECT 1 FROM stable_projection_writes p WHERE p.spreadsheet_id=NEW.spreadsheet_id AND p.entity_type='EXPENSE' AND p.entity_id=json_extract(item.value,'$.entity_id') AND p.projection=json_extract(item.value,'$.projection') AND p.sheet_id=json_extract(item.value,'$.sheet_id') AND p.sheet_name=json_extract(item.value,'$.sheet_name') AND p.source_version=json_extract(item.value,'$.source_version') AND p.source_digest=json_extract(item.value,'$.source_digest') AND p.operation_token=json_extract(item.value,'$.operation_token') AND p.state='VERIFIED' AND (NEW.operation_kind='CANCEL' AND p.source_version=NEW.source_version-1 OR NEW.operation_kind='CONFIRM' AND p.source_version=NEW.source_version AND p.source_digest=NEW.source_digest)))
 OR (NEW.operation_kind='CONFIRM' AND EXISTS(SELECT 1 FROM stable_expense_cancellation_writes w WHERE w.spreadsheet_id=NEW.spreadsheet_id AND w.entity_type='EXPENSE' AND (w.entity_id=NEW.expense_id OR substr(w.entity_id,1,length(NEW.expense_id)+1)=NEW.expense_id||'|')))
 OR (NEW.operation_kind='CANCEL' AND ((SELECT count(*) FROM stable_expense_cancellation_writes w WHERE w.spreadsheet_id=NEW.spreadsheet_id AND w.entity_type='EXPENSE' AND (w.entity_id=NEW.expense_id OR substr(w.entity_id,1,length(NEW.expense_id)+1)=NEW.expense_id||'|'))<>json_array_length(NEW.journal_manifest) OR EXISTS(SELECT 1 FROM json_each(NEW.journal_manifest) item WHERE NOT EXISTS(SELECT 1 FROM stable_expense_cancellation_writes w WHERE w.spreadsheet_id=NEW.spreadsheet_id AND w.entity_type='EXPENSE' AND w.entity_id=json_extract(item.value,'$.entity_id') AND w.projection=json_extract(item.value,'$.projection') AND w.cancellation_version=NEW.source_version AND w.previous_version=json_extract(item.value,'$.source_version') AND w.operation_token=json_extract(item.value,'$.cancel_operation_token') AND w.preimage_digest=json_extract(item.value,'$.cancel_preimage_digest') AND w.state='VERIFIED'))))
 OR (SELECT count(*) FROM stable_projection_writes p WHERE p.spreadsheet_id=NEW.spreadsheet_id AND p.operation_token=NEW.operation_token)+(SELECT count(*) FROM stable_expense_cancellation_writes w WHERE w.spreadsheet_id=NEW.spreadsheet_id AND w.operation_token=NEW.operation_token)<>0
BEGIN SELECT RAISE(ABORT,'final evidence requires exact checked target'); END;
CREATE TRIGGER IF NOT EXISTS continuous_final_notice_evidence_no_update BEFORE UPDATE ON continuous_final_notice_evidence BEGIN SELECT RAISE(ABORT,'final evidence immutable'); END;
CREATE TRIGGER IF NOT EXISTS continuous_final_notice_evidence_no_delete BEFORE DELETE ON continuous_final_notice_evidence BEGIN SELECT RAISE(ABORT,'final evidence retained'); END;
CREATE TRIGGER IF NOT EXISTS continuous_final_notice_evidence_no_replace BEFORE INSERT ON continuous_final_notice_evidence WHEN EXISTS(SELECT 1 FROM continuous_final_notice_evidence x WHERE x.operation_token=NEW.operation_token OR x.rowid=NEW.rowid) BEGIN SELECT RAISE(ABORT,'final evidence already exists'); END;
